def maxCoins(nums):
    vals = [1] + [x for x in nums if x > 0] + [1]
    n = len(vals)
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n - 1):
        for left in range(0, n - length - 1):
            right = left + length + 1
            for i in range(left + 1, right):
                dp[left][right] = max(
                    dp[left][right],
                    vals[left] * vals[i] * vals[right] + dp[left][i] + dp[i][right]
                )
    return dp[0][n - 1]
